"""
Curated subject catalogue for the size-guessing game.

Every measurement is in METRES.
  h  = height (vertical extent as the object normally stands / is pictured)
  l  = length (horizontal extent in a side view; wingspan for flying shots)
  d  = diameter (spheres) -> counts as both height and length

conf:
  official  - manufacturer, governing body, franchise/canon guide, survey authority
  measured  - scientific measurement of a specific object
  typical   - typical adult / representative value for a species or class (approx.)
  estimate  - scientific or fan estimate with real uncertainty (always labelled in game)

img candidates (tried in order by build_assets.py):
  "w:Title"  lead image of the English Wikipedia article
  "f:Name"   a specific Wikimedia Commons / Wikipedia file
  "s:terms"  Wikimedia Commons file search
fit: ("h"|"w", fraction) -> the measured dimension spans `fraction` of the cut-out's
     height ("h") or width ("w").  Default: l -> width, otherwise height.
"""

SUBJECTS = []


def S(id, cat, en, ar, conf, src, img=None, note=None, fit=None, tier=2, crop=None, model=None, skip=False, **dims):
    SUBJECTS.append(dict(id=id, cat=cat, en=en, ar=ar, conf=conf, src=src,
                         img=img or [f"w:{en}"], note=note, fit=fit, tier=tier,
                         crop=crop, model=model, skip=skip, dims=dims))


